+export async function handlePayout(req: Request, res: Response) {
+  const sig = req.header('X-Signature') ?? '';
+  const expected = createHmac('sha256', process.env.PAYOUT_WEBHOOK_SECRET!).update(JSON.stringify(req.body)).digest('hex');
+  if (sig !== expected) return res.status(401).end();
+  const evt = req.body as PayoutEvent;
+  await payouts.markSettled(evt.payout_id, evt.amount);
+  res.status(200).end();
+}
